import{_ as l,a0 as o,w as r,s as d,I as a,x as n,a1 as e,A as t,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"awk 系列：怎樣使用 awk 變量、數值表達式以及賦值運算符 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：怎樣使用 awk 變量、數值表達式以及賦值運算符 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：怎樣使用 awk 變量、數值表達式以及賦值運算符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：怎樣使用 awk 變量、數值表達式以及賦值運算符 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 8 - Learn How to Use Awk Variables, Numeric Expressions and Assignment Operators","title":"awk 系列：怎樣使用 awk 變量、數值表達式以及賦值運算符","tag":"awk","desc":""},"relativePath":"awk/Part 8 - Learn How to Use Awk Variables, Numeric Expressions and Assignment Operators.md","filePath":"[post].md"}'),c={name:"awk/Part 8 - Learn How to Use Awk Variables, Numeric Expressions and Assignment Operators.md"};function m(k,s,h,u,g,b){const i=o("Link");return r(),d("div",null,[s[27]||(s[27]=a("h1",{id:"awk-系列-怎樣使用-awk-變量、數值表達式以及賦值運算符",tabindex:"-1"},[n("awk 系列：怎樣使用 awk 變量、數值表達式以及賦值運算符 "),a("a",{class:"header-anchor",href:"#awk-系列-怎樣使用-awk-變量、數值表達式以及賦值運算符","aria-label":"Permalink to “awk 系列：怎樣使用 awk 變量、數值表達式以及賦值運算符”"},"​")],-1)),a("p",null,[s[1]||(s[1]=n("我覺得 ",-1)),e(i,{href:"https://linux.cn/article-7586-1.html"},{default:t(()=>[...s[0]||(s[0]=[n("awk 系列",-1)])]),_:1}),s[2]||(s[2]=n(" 將會越來越好，在本系列的前七節我們討論了在 Linux 中處理文件和篩選字符串所需要的一些 awk 命令基礎。",-1))]),s[28]||(s[28]=p(`<p>在這一部分，我們將會進入 awk 更高級的部分，使用 awk 處理更復雜的文本和進行字符串過濾操作。因此，我們將會講到 Awk 的一些特性，諸如變量、數值表達式和賦值運算符。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Learn-Awk-Variables-Numeric-Expressions-Assignment-Operators.png" alt=""></p><p><em>學習 Awk 變量，數值表達式和賦值運算符</em></p><p>你可能已經在很多編程語言中接觸過它們，比如 shell，C，Python 等；這些概念在理解上和這些語言沒有什麼不同，所以在這一小節中你不用擔心很難理解，我們將會簡短的提及常用的一些 awk 特性。</p><p>這一小節可能是 awk 命令裏最容易理解的部分，所以放鬆點，我們開始吧。</p><h3 id="_1-awk-變量" tabindex="-1">1. Awk 變量 <a class="header-anchor" href="#_1-awk-變量" aria-label="Permalink to “1. Awk 變量”">​</a></h3><p>在很多編程語言中，變量就是一個存儲了值的佔位符，當你在程序中新建一個變量的時候，程序一運行就會在內存中創建一些空間，你為變量賦的值會存儲在這些內存空間上。</p><p>你可以像下面這樣定義 shell 變量一樣定義 Awk 變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>variable_name=value</span></span></code></pre></div><p>上面的語法：</p><ul><li><code>variable_name</code>: 為定義的變量的名字</li><li><code>value</code>: 為變量賦的值</li></ul><p>再看下面的一些例子:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>computer_name=”tecmint.com”</span></span>
<span class="line"><span>port_no=”22”</span></span>
<span class="line"><span>email=”admin@tecmint.com”</span></span>
<span class="line"><span>server=computer_name</span></span></code></pre></div><p>觀察上面的簡單的例子，在定義第一個變量的時候，值 &#39;tecmint.com&#39; 被賦給了 &#39;computer_name&#39; 變量。</p><p>此外，值 22 也被賦給了 port_no 變量，把一個變量的值賦給另一個變量也是可以的，在最後的例子中我們把變量 computer_name 的值賦給了變量 server。</p>`,15)),a("p",null,[s[4]||(s[4]=n("你可以看看",-1)),e(i,{href:"https://linux.cn/article-7587-1.html"},{default:t(()=>[...s[3]||(s[3]=[n("本系列的第 2 節",-1)])]),_:1}),s[5]||(s[5]=n("中提到的字段編輯，我們討論了 awk 怎樣將輸入的行分隔為若干字段並且使用標準字段訪問操作符 ",-1)),s[6]||(s[6]=a("code",null,"$",-1)),s[7]||(s[7]=n(" 來訪問拆分出來的不同字段。我們也可以像下面這樣使用變量為字段賦值。",-1))]),s[29]||(s[29]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>first_name=$2</span></span>
<span class="line"><span>second_name=$3</span></span></code></pre></div><p>在上面的例子中，變量 first_name 的值設置為第二個字段，second_name 的值設置為第三個字段。</p>`,2)),a("p",null,[s[9]||(s[9]=n("再舉個例子，有一個名為 names.txt 的文件，這個文件包含了一個應用程序的用户列表，這個用户列表包含了用户的名和姓以及性別。可以使用 ",-1)),e(i,{href:"http://www.tecmint.com/13-basic-cat-command-examples-in-linux/"},{default:t(()=>[...s[8]||(s[8]=[n("cat 命令",-1)])]),_:1}),s[10]||(s[10]=n(" 查看文件內容：",-1))]),s[30]||(s[30]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat names.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/List-File-Content-Using-cat-Command.png" alt=""></p><p><em>使用 cat 命令查看列表文件內容</em></p><p>然後，我們也可以使用下面的 awk 命令把列表中第一個用户的第一個和第二個名字分別存儲到變量 first_name 和 second_name 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;/Aaron/{ first_name=$2 ; second_name=$3 ; print first_name, second_name ; }&#39; names.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Store-Variables-Using-Awk-Command.png" alt=""></p><p><em>使用 Awk 命令為變量賦值</em></p><p>再看一個例子，當你在終端運行 &#39;uname -a&#39; 時，它可以打印出所有的系統信息。</p><p>第二個字段包含了你的主機名，因此，我們可以像下面這樣把它賦給一個叫做 hostname 的變量並且用 awk 打印出來。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -a</span></span>
<span class="line"><span>$ uname -a | awk &#39;{hostname=$2 ; print hostname ; }&#39;</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Store-Command-Output-to-Variable-Using-Awk.png" alt=""></p><p><em>使用 Awk 把命令的輸出賦給變量</em></p><h3 id="_2-數值表達式" tabindex="-1">2. 數值表達式 <a class="header-anchor" href="#_2-數值表達式" aria-label="Permalink to “2. 數值表達式”">​</a></h3><p>在 Awk 中，數值表達式使用下面的數值運算符組成：</p><ul><li><code>*</code> : 乘法運算符</li><li><code>+</code> : 加法運算符</li><li><code>/</code> : 除法運算符</li><li><code>-</code> : 減法運算符</li><li><code>%</code> : 取模運算符</li><li><code>^</code> : 指數運算符</li></ul><p>數值表達式的語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ operand1 operator operand2</span></span></code></pre></div><p>上面的 operand1 和 operand2 可以是數值和變量，運算符可以是上面列出的任意一種。</p><p>下面是一些展示怎樣使用數值表達式的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>counter=0</span></span>
<span class="line"><span>num1=5</span></span>
<span class="line"><span>num2=10</span></span>
<span class="line"><span>num3=num2-num1</span></span>
<span class="line"><span>counter=counter+1</span></span></code></pre></div><p>要理解 Awk 中數值表達式的用法，我們可以看看下面的例子，文件 domians.txt 裏包括了所有屬於 Tecmint 的域名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>windows.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>windows.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span></code></pre></div><p>可以使用下面的命令查看文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat domains.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/View-Contents-of-File.png" alt=""></p><p><em>查看文件內容</em></p><p>如果想要計算出域名 tecmint.com 在文件中出現的次數，我們就可以通過寫一個簡單的腳本實現這個功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for file in $@; do</span></span>
<span class="line"><span>if [ -f $file ] ; then</span></span>
<span class="line"><span>#print out filename</span></span>
<span class="line"><span>echo &quot;File is: $file&quot;</span></span>
<span class="line"><span>#print a number incrementally for every line containing tecmint.com </span></span>
<span class="line"><span>awk  &#39;/^tecmint.com/ { counter=counter+1 ; printf &quot;%s\\n&quot;, counter ; }&#39;   $file</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>#print error info incase input is not a file</span></span>
<span class="line"><span>echo &quot;$file is not a file, please specify a file.&quot; &gt;&amp;2 &amp;&amp; exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>#terminate script with exit code 0 in case of successful execution </span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Shell-Script-to-Count-a-String-in-File.png" alt=""></p><p><em>計算一個字符串或文本在文件中出現次數的 shell 腳本</em></p><p>寫完腳本後保存並賦予執行權限，當我們使用文件運行腳本的時候，文件 domains.txt 作為腳本的輸入，我們會得到下面的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./script.sh  ~/domains.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Script-To-Count-String.png" alt=""></p><p><em>計算字符串或文本出現次數的腳本</em></p><p>從腳本執行後的輸出中，可以看到在文件 domains.txt 中包含域名 tecmint.com 的地方有 6 行，你可以自己計算進行驗證。</p><h3 id="_3-賦值操作符" tabindex="-1">3. 賦值操作符 <a class="header-anchor" href="#_3-賦值操作符" aria-label="Permalink to “3. 賦值操作符”">​</a></h3><p>我們要説的最後的 Awk 特性是賦值操作符，下面列出的只是 awk 中的部分賦值運算符：</p><ul><li><code>*=</code> : 乘法賦值操作符</li><li><code>+=</code> : 加法賦值操作符</li><li><code>/=</code> : 除法賦值操作符</li><li><code>-=</code> : 減法賦值操作符</li><li><code>%=</code> : 取模賦值操作符</li><li><code>^=</code> : 指數賦值操作符</li></ul><p>下面是 Awk 中最簡單的一個賦值操作的語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ variable_name=variable_name operator operand</span></span></code></pre></div><p>例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>counter=0</span></span>
<span class="line"><span>counter=counter+1</span></span>
<span class="line"><span>num=20</span></span>
<span class="line"><span>num=num-1</span></span></code></pre></div><p>你可以使用在 awk 中使用上面的賦值操作符使命令更簡短，從先前的例子中，我們可以使用下面這種格式進行賦值操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>variable_name operator=operand</span></span>
<span class="line"><span>counter=0</span></span>
<span class="line"><span>counter+=1</span></span>
<span class="line"><span>num=20</span></span>
<span class="line"><span>num-=1</span></span></code></pre></div><p>因此，我們可以在 shell 腳本中改變 awk 命令，使用上面提到的 += 操作符:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for file in $@; do</span></span>
<span class="line"><span>if [ -f $file ] ; then</span></span>
<span class="line"><span>#print out filename</span></span>
<span class="line"><span>echo &quot;File is: $file&quot;</span></span>
<span class="line"><span>#print a number incrementally for every line containing tecmint.com </span></span>
<span class="line"><span>awk  &#39;/^tecmint.com/ { counter+=1 ; printf  &quot;%s\\n&quot;,  counter ; }&#39;   $file</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>#print error info incase input is not a file</span></span>
<span class="line"><span>echo &quot;$file is not a file, please specify a file.&quot; &gt;&amp;2 &amp;&amp; exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>#terminate script with exit code 0 in case of successful execution </span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Alter-Shell-Script.png" alt=""></p><p><em>修改了的 shell 腳本</em></p>`,48)),a("p",null,[s[12]||(s[12]=n("在 ",-1)),e(i,{href:"https://linux.cn/article-7586-1.html"},{default:t(()=>[...s[11]||(s[11]=[n("awk 系列",-1)])]),_:1}),s[13]||(s[13]=n(" 的這一部分，我們討論了一些有用的 awk 特性，有變量，使用數值表達式和賦值運算符，還有一些使用它們的實例。",-1))]),s[31]||(s[31]=a("p",null,"這些概念和其他的編程語言沒有任何不同，但是可能在 awk 中有一些意義上的區別。",-1)),s[32]||(s[32]=a("p",null,"在本系列的第 9 節，我們會學習更多的 awk 特性，比如特殊格式： BEGIN 和 END。請繼續關注。",-1)),s[33]||(s[33]=a("hr",null,null,-1)),a("p",null,[s[15]||(s[15]=n("via: ",-1)),e(i,{href:"http://www.tecmint.com/learn-awk-variables-numeric-expressions-and-assignment-operators/"},{default:t(()=>[...s[14]||(s[14]=[n("http://www.tecmint.com/learn-awk-variables-numeric-expressions-and-assignment-operators/",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=n("作者：",-1)),e(i,{href:"http://www.tecmint.com/author/aaronkili/"},{default:t(()=>[...s[16]||(s[16]=[n("Aaron Kili",-1)])]),_:1}),s[20]||(s[20]=n(" 譯者：",-1)),e(i,{href:"https://github.com/vim-kakali"},{default:t(()=>[...s[17]||(s[17]=[n("vim-kakali",-1)])]),_:1}),s[21]||(s[21]=n(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[18]||(s[18]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[24]||(s[24]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[22]||(s[22]=[n("LCTT",-1)])]),_:1}),s[25]||(s[25]=n(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[23]||(s[23]=[n("Linux中國",-1)])]),_:1}),s[26]||(s[26]=n(" 榮譽推出",-1))])])}const y=l(c,[["render",m]]);export{x as __pageData,y as default};
